"""Real JEE Main questions — Physics Unit 5: Rotational Motion. Our own solutions; chk re-solves each one — moments of
inertia and centres of mass of cut discs/plates by summing over a fine grid, rotations and rolling by stepping the
equations of motion, collisions of spinning bodies from angular-momentum conservation written out afresh. Skipped:
a ring-vs-sphere speed ratio whose stated form √(x/5) has no whole-number x, a ring-vs-sphere KE ratio that needs
unstated equal masses, a disc/ring item whose premise (2.5 times) contradicts the standard results, a rod/sphere
item whose key does not follow from the figure, and figure-only items (cut-out discs with unclear axes, a triangle
of masses whose coordinates are only in the drawing)."""
import math
from common import new_registry, pick, near, verify
P, add = new_registry()
G = 10.0
def grid(R, n=500):   # points of a square grid covering a disc of radius R (cell area returned)
    h = 2 * R / n; pts = [(-R + (i + 0.5) * h, -R + (j + 0.5) * h) for i in range(n) for j in range(n)]
    return [(x, y) for x, y in pts if x * x + y * y <= R * R], h * h
def cut_disc(R, holes, n=500):   # uniform disc with circular holes [(cx, cy, r)]: returns (area, Σx dA, Σ r² dA)
    pts, dA = grid(R, n); keep = [(x, y) for x, y in pts if all((x - a) ** 2 + (y - b) ** 2 > r * r for a, b, r in holes)]
    return len(keep) * dA, sum(x for x, _ in keep) * dA, sum(x * x + y * y for x, y in keep) * dA
def rod_I(L, d0, n=20000):   # rod from d0 to d0 + L along a line perpendicular to the axis, unit mass
    h = L / n; return sum((d0 + (i + 0.5) * h) ** 2 for i in range(n)) * h / L
def sph_I(R=1.0, n=20000):   # solid sphere about a diameter, by shells: ∫ (2/3) r² dm, unit mass
    h = R / n; m = [4 * math.pi * ((i + 0.5) * h) ** 2 * h for i in range(n)]; M = sum(m); return sum(mi * (2 / 3) * ((i + 0.5) * h) ** 2 for i, mi in enumerate(m)) / M
def cross(a, b): return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])

