# ---------------- torque and rotational dynamics ----------------
add(('2025', 'Apr', '2025-04-02', 1), 'torq', 'A cord of negligible mass is wound around the rim of a wheel supported by spokes with negligible mass. The mass of wheel is 10 kg and radius is 10 cm and it can freely rotate without any friction. Initially the wheel is at rest. If a steady pull of 20 N is applied on the cord, the angular velocity of the wheel, after the cord is unwound by 1 m, would be :', ['10 rad/s', '30 rad/s', '20 rad/s', '0 rad/s'], 3,
    lambda: pick([10, 30, 20, 0], round(math.sqrt(2 * 20 * 1 / (10 * 0.1 ** 2)), 6)), ['All mass on the rim: I = MR^{2} = 0.1 kg m^{2}.', 'Work 20 × 1 = ½Iω^{2} → ω^{2} = 400 → ω = 20 rad/s.'], 'torq', 2)
